Here's a C++ function that converts markdown formatted text into HTML formatted text:

```cpp
#include <iostream>
#include <vector>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    std::string html;
    std::vector<std::string> lines;

    for (const auto& line : markdown) {
        if (line.empty()) continue;

        std::string line = line;
        std::istringstream iss(line);

        while (iss >> line) {
            html += "<p>" + line + "</p>";
        }
    }

    return html;
}
```

This function takes a reference to a `std::string` containing markdown formatted text and returns a `std::string` with HTML formatted text. The function splits the markdown text into lines, converts each line to HTML, and concatenates them together.

Here's an example usage:

```cpp
int main() {
    std::string markdown = "# Hello World\n- This is a list\n- Item 1";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

This will output the HTML formatted text, with each line wrapped in `<p>` tags.

